#pragma once
// Facts about each hookable stock function entry (table generated by tools/gen_prologues.py).

#include <windows.h>

namespace nw {

enum PrologueFlags
{
    PF_REL32 = 1,    // stolen bytes contain a call/jmp/jcc rel32 (trampoline re-targets it)
    PF_NOTRAMP = 2,  // no trampoline possible (rel8 branch in / into the stolen bytes)
    PF_ENDS = 4,     // the function returns inside the stolen bytes
};

struct Prologue
{
    DWORD va;
    BYTE steal;      // whole-instruction bytes covering the first 5
    WORD room;       // bytes that may be overwritten at the entry (body + padding)
    BYTE flags;
    BYTE relat;      // offset of the rel32 call/jmp/jcc inside the stolen bytes (0xFF: none)
    BYTE relmask;    // bit i: expect[i] is part of a relocated dword
    BYTE expect[8];  // first stock bytes
};

extern const Prologue kPrologues[];
extern const unsigned kPrologueCount;

}  // namespace nw
